package com.bank.continuous;

import java.util.*;

public class ContinuousRouter {

    public ThreadNode connectAll(ThreadNode root) {
        if (root == null) return null;
        Queue<ThreadNode> queue = new LinkedList<>();
        queue.offer(root);
        ThreadNode previous = null;                 // ONE pointer for the whole tree
        while (!queue.isEmpty()) {
            ThreadNode node = queue.poll();
            if (previous != null) previous.next = node;  // link across levels too
            previous = node;
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        // final node's next stays null
        return root;
    }
}
