package com.bank.continuous;

import java.util.logging.Logger;

public class ConnectAllDemo {
    private static final Logger log = Logger.getLogger(ConnectAllDemo.class.getName());

    public static void main(String[] args) {
        ThreadNode root = new ThreadNode(1);
        root.left = new ThreadNode(2);
        root.right = new ThreadNode(3);
        root.left.left = new ThreadNode(4);
        root.left.right = new ThreadNode(5);
        root.right.left = new ThreadNode(6);
        root.right.right = new ThreadNode(7);

        new ContinuousRouter().connectAll(root);

        StringBuilder sb = new StringBuilder();
        for (ThreadNode n = root; n != null; n = n.next) {
            sb.append(n.id).append(n.next != null ? " -> " : " -> null");
        }
        log.info("Continuous chain: " + sb);
    }
}
